  {type:"word-family",topic:"Word families · Diagnose",prompt:"Choose the correct noun.",sentence:"Early ______ can improve the chance of effective treatment.",options:["diagnosis","diagnose","diagnostic","diagnostically"],answer:"diagnosis",explanation:"A noun is required as the subject of the sentence."},
  {type:"word-family",topic:"Word families · Economy",prompt:"Choose the adjective that modifies migration.",sentence:"Wage differences can influence patterns of ______ migration.",options:["economic","economy","economically","economise"],answer:"economic",explanation:"Economic is the adjective modifying migration."},
  {type:"word-family",topic:"Word families · Compare",prompt:"Choose the correct adjective.",sentence:"The two regions recorded broadly ______ rates of growth.",options:["comparable","comparison","compare","comparably"],answer:"comparable",explanation:"An adjective is needed before rates."},
  {type:"word-family",topic:"Word families · Account",prompt:"Choose the correct adjective.",sentence:"Public bodies should be ______ for their spending decisions.",options:["accountable","account","accountability","accountably"],answer:"accountable",explanation:"After should be, an adjective is required."},

  {type:"matching",topic:"Sentence logic · Contrast",prompt:"Choose the best second half.",sentence:"Whereas rail use rose throughout the period, ...",options:["the proportion travelling by bus declined steadily.","because rail use was a public system.","therefore both figures were exactly identical.","the chart has four colours in total."],answer:"the proportion travelling by bus declined steadily.",explanation:"Whereas connects two contrasting trends."},
  {type:"matching",topic:"Sentence logic · Result",prompt:"Choose the best second half.",sentence:"The city introduced frequent night buses; as a consequence, ...",options:["fewer workers needed to drive after late shifts.","owing to the buses were frequent.","although the policy caused a reason.","the city introducing a bus."],answer:"fewer workers needed to drive after late shifts.",explanation:"As a consequence should be followed by a logical result."},
  {type:"matching",topic:"Sentence logic · Concession",prompt:"Choose the best second half.",sentence:"Although automation can improve productivity, ...",options:["it may displace workers in routine roles.","because every worker will receive promotion.","therefore it has no potential drawbacks.","the machines despite are expensive."],answer:"it may displace workers in routine roles.",explanation:"Although signals that the main clause will present a contrasting limitation."},
  {type:"matching",topic:"Task 1 · Process",prompt:"Choose the best second half.",sentence:"After the material has been heated, ...",options:["it is transferred to a cooling chamber.","workers will heated it before.","the chart was rising rapidly.","although a cooling chamber."],answer:"it is transferred to a cooling chamber.",explanation:"The passive clause describes a logical next process stage."},
  {type:"matching",topic:"Task 2 · Environment",prompt:"Choose the best second half.",sentence:"Unless poaching is controlled, ...",options:["several endangered species may disappear from the region.","conservation programmes had protected every animal yesterday.","wildlife is renewable because.","the ecosystem was a financial incentive."],answer:"several endangered species may disappear from the region.",explanation:"Unless introduces a condition whose absence leads to the stated risk."},
  {type:"matching",topic:"Task 2 · Education",prompt:"Choose the best second half.",sentence:"By using continuous assessment, schools can ...",options:["reward consistent effort across the academic year.","resit every student from a qualification.","make literacy is a final examination.","although pupils have several assignments."],answer:"reward consistent effort across the academic year.",explanation:"The second half explains a logical benefit of assessment over time."},
  {type:"matching",topic:"Task 2 · Media",prompt:"Choose the best second half.",sentence:"Before sharing a dramatic news report, readers should ...",options:["verify the source and examine the supporting evidence.","assume a popular headline is always accurate.","be shared by every account immediately.","the documentary was a tabloid."],answer:"verify the source and examine the supporting evidence.",explanation:"The clause completes the recommendation with two appropriate actions."},
  {type:"matching",topic:"Task 2 · Government",prompt:"Choose the best second half.",sentence:"A regulation is unlikely to change behaviour unless ...",options:["the authorities enforce it consistently.","the policy is account for.","public expenditure was a result linker.","it has been a traditional value."],answer:"the authorities enforce it consistently.",explanation:"The sentence links regulation with the enforcement needed for impact."},

  {type:"highlight",topic:"Paragraph structure · Topic sentence",prompt:"Which sentence is the topic sentence?",sentence:"Select the sentence that states the paragraph’s controlling claim.",options:["Continuous assessment can provide a fairer picture of student ability than one final exam.","It rewards consistent work completed throughout the course.","It can also reduce the effect of illness or anxiety on a single test day.","For example, a strong project may balance a weaker timed paper."],answer:"Continuous assessment can provide a fairer picture of student ability than one final exam.",explanation:"It presents the main comparison developed by the rest of the paragraph."},
  {type:"highlight",topic:"Paragraph structure · Supporting idea",prompt:"Which sentence is a supporting idea?",sentence:"Identify the general reason that develops the claim.",options:["Investment in cycle lanes can reduce congestion.","Safe routes encourage commuters to replace short car journeys with bicycles.","For instance, one protected route may connect a suburb to a station.","This change can also improve local air quality."],answer:"Safe routes encourage commuters to replace short car journeys with bicycles.",explanation:"It explains the mechanism behind the topic sentence."},
  {type:"highlight",topic:"Paragraph structure · Example",prompt:"Which sentence is the example?",sentence:"Choose the concrete illustration.",options:["Automation can remove repetitive tasks from manufacturing.","This allows some employees to focus on quality control and maintenance.","For example, a packaging machine can seal hundreds of boxes per hour.","However, workers may need retraining to move into new roles."],answer:"For example, a packaging machine can seal hundreds of boxes per hour.",explanation:"It gives a specific illustration of automated repetitive work."},
  {type:"highlight",topic:"Paragraph structure · Topic sentence",prompt:"Which sentence is the topic sentence?",sentence:"Choose the sentence that introduces the paragraph’s central idea.",options:["Local media can strengthen community engagement.","It can report decisions that directly affect nearby residents.","This information may encourage more people to attend public meetings.","For instance, a neighbourhood paper might explain a proposed bus route."],answer:"Local media can strengthen community engagement.",explanation:"The other sentences explain and illustrate this main claim."},
  {type:"highlight",topic:"Paragraph structure · Supporting idea",prompt:"Which sentence is a supporting idea?",sentence:"Select the sentence that provides a reason rather than the main claim or example.",options:["Preventive healthcare can reduce pressure on hospitals.","Early screening allows some conditions to be treated before they become severe.","For example, routine blood-pressure checks can identify patients at risk.","Consequently, fewer people may require emergency treatment."],answer:"Early screening allows some conditions to be treated before they become severe.",explanation:"It explains why preventive care can reduce pressure."},
  {type:"highlight",topic:"Paragraph structure · Example",prompt:"Which sentence is the example?",sentence:"Select the specific illustration.",options:["Flexible courses can widen access to higher education.","They allow mature students to fit study around employment and care.","For example, a parent could watch a recorded lecture after a child is asleep.","This flexibility may increase course completion."],answer:"For example, a parent could watch a recorded lecture after a child is asleep.",explanation:"The scenario illustrates how flexibility supports a mature student."},
  {type:"highlight",topic:"Paragraph structure · Topic sentence",prompt:"Which sentence is the topic sentence?",sentence:"Find the broad claim that organises the paragraph.",options:["Wildlife conservation must involve nearby communities to succeed in the long term.","Residents often possess detailed knowledge of local habitats.","Conservation jobs can also provide alternatives to poaching.","For example, former hunters may be trained as park rangers."],answer:"Wildlife conservation must involve nearby communities to succeed in the long term.",explanation:"It makes the broad claim supported by the following reasons and example."},
  {type:"highlight",topic:"Paragraph structure · Concluding sentence",prompt:"Which sentence best concludes the paragraph?",sentence:"Select the sentence that draws the ideas together.",options:["Job security affects both workers and employers.","Secure staff may be more willing to develop specialised skills.","Firms can then retain experience and reduce recruitment costs.","Therefore, reasonable job security can support a stable and productive workforce."],answer:"Therefore, reasonable job security can support a stable and productive workforce.",explanation:"Therefore signals a conclusion that synthesises the supporting points."}
